#include <string>
using namespace std;

int main() {
    string s, t;
    cin >> s >> t;

    int j = 0;
    for (int i = 0; i < static_cast<int>(t.size()); ++i) {
        if (s[j] == t[i]) {
            ++j;
        }
    }

    cout << j + 1;
    return 0;
}

